const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry (point at Beaufort Sea)
  const lon = -136.325766;
  const lat = 69.954148;
  const point = ee.Geometry.Point([lon, lat]);
  const buffer = point.buffer(5000); // 5km buffer for analysis

  // 2. Define time periods
  const date1_start = '2012-06-10';
  const date1_end = '2012-06-18';
  const date2_start = '2012-07-01';
  const date2_end = '2012-07-10';

  // 3. Load Landsat 7 (available for 2012)
  const col1 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(buffer)
    .filterDate(date1_start, date1_end)
    .filter(ee.Filter.lt('CLOUD_COVER', 50));

  const col2 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(buffer)
    .filterDate(date2_start, date2_end)
    .filter(ee.Filter.lt('CLOUD_COVER', 50));

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log('June 2012 Images: ' + size1);
  console.log('July 2012 Images: ' + size2);

  // Check for empty collections
  if (size1 === 0 || size2 === 0) {
    console.log('Insufficient data for one or both dates.');
    console.log('C1');
    return;
  }

  // 4. Prepare images and mask clouds
  const prepareImage = function(img) {
    // QA_PIXEL band for cloud masking
    const qa = img.select('QA_PIXEL');
    const cloud = qa.bitwiseAnd(32).eq(0)
      .and(qa.bitwiseAnd(64).eq(0));
    return img.updateMask(cloud).select(['SR_B1', 'SR_B2', 'SR_B3', 'SR_B4']);
  };

  const img1 = col1.map(prepareImage).mosaic();
  const img2 = col2.map(prepareImage).mosaic();

  // 5. Calculate turbidity index (Red/Blue ratio as proxy for turbidity)
  // Higher ratio = higher turbidity
  const turbidity1 = img1.select('SR_B3').divide(img1.select('SR_B1'))
    .rename('turbidity');
  const turbidity2 = img2.select('SR_B3').divide(img2.select('SR_B1'))
    .rename('turbidity');

  // 6. Extract turbidity values
  const stats1 = turbidity1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 3000,
    maxPixels: 1e9
  });

  const stats2 = turbidity2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 3000,
    maxPixels: 1e9
  });

  // Check pixel counts
  const count1 = turbidity1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 3000,
    maxPixels: 1e9
  });

  const count2 = turbidity2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 3000,
    maxPixels: 1e9
  });

  const val1 = stats1.get('turbidity').getInfo();
  const val2 = stats2.get('turbidity').getInfo();
  const cnt1 = count1.get('turbidity').getInfo();
  const cnt2 = count2.get('turbidity').getInfo();

  console.log('June Turbidity: ' + (val1 !== null ? val1.toFixed(4) : 'null') + ' (Pixels: ' + cnt1 + ')');
  console.log('July Turbidity: ' + (val2 !== null ? val2.toFixed(4) : 'null') + ' (Pixels: ' + cnt2 + ')');

  // 7. Validation
  if (cnt1 === 0 || cnt2 === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('C2');
    return;
  }

  if (val1 === null || val2 === null || isNaN(val1) || isNaN(val2)) {
    console.log('Invalid turbidity calculation.');
    console.log('C3');
    return;
  }

  // 8. Final comparison
  const increased = val2 > val1;

  if (increased) {
    console.log('Turbidity increased from June to July.');
    console.log('A');
  } else {
    console.log('Turbidity did not increase.');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
